std::randomgen rand_gen(seed);
int hits = 0;
for (int i = 0; i < n_points; i++) {
    double x = rand_gen.uniform(a, b);
    double y = rand_gen.uniform(0, fmax);
    if (y <= f(x)) {
        hits++;
    }
}
double integral_estimate = (static_cast<double>(hits) / n_points) * (b - a) * fmax;
return integral_estimate;

